package com.smart.agent.tool.progress;
import com.fasterxml.jackson.databind.*;import com.smart.agent.tool.*;import com.smart.agent.tool.project.ProjectQueryResult;import java.util.*;import java.time.*;import java.nio.charset.StandardCharsets;import java.util.Base64;import javax.crypto.Mac;import javax.crypto.spec.SecretKeySpec;import org.springframework.web.reactive.function.client.*;import org.springframework.http.*;
public class SmartBootProjectProgressBusinessClient implements ProjectProgressBusinessClient{private static final String PATH="/internal/ai/tools/project-progress-query";private final WebClient client;private final ObjectMapper mapper;private final String secret;public SmartBootProjectProgressBusinessClient(WebClient c,ObjectMapper m,String s){client=c;mapper=m;secret=s;}public ProjectQueryResult query(ToolContext c,ProjectProgressQueryInput i){if(i.projectId()!=null&&!c.projectIds().contains(i.projectId()))throw new SecurityException("当前账号暂时无法查看该项目的施工进度");Map<String,Object>b=new LinkedHashMap<>();b.put("projectIds",i.projectId()==null?c.projectIds():List.of(i.projectId()));b.put("projectName",i.projectName());b.put("mode",i.mode());b.put("dateField",i.dateField());b.put("startDate",i.startDate());b.put("endDate",i.endDate());b.put("page",i.page());b.put("pageSize",i.pageSize());try{return mapper.readValue(client.post().uri(PATH).headers(h->sign(h,c)).bodyValue(b).retrieve().bodyToMono(String.class).block(),ProjectQueryResult.class);}catch(Exception e){throw new RuntimeException("施工进度查询暂时失败",e);}}private void sign(HttpHeaders h,ToolContext c){String t=String.valueOf(Instant.now().getEpochSecond()),roles=String.join(",",new TreeSet<>(c.roleIds())),perms=String.join(",",new TreeSet<>(c.permissions())),projects=String.join(",",new TreeSet<>(c.projectIds()));h.set("X-Agent-Internal-Timestamp",t);h.set("X-Agent-Tenant-Id",c.tenantId());h.set("X-Agent-User-Id",c.userId());h.set("X-Agent-Identity-Id",c.identityId());h.set("X-Agent-Role-Ids",roles);h.set("X-Agent-Permissions",perms);h.set("X-Agent-Project-Ids",projects);try{Mac m=Mac.getInstance("HmacSHA256");m.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));String canonical=t+"\nPOST\n"+PATH+"\n"+c.tenantId()+"\n"+c.userId()+"\n"+c.identityId()+"\n"+roles+"\n"+perms+"\n"+projects;h.set("X-Agent-Internal-Signature",Base64.getUrlEncoder().withoutPadding().encodeToString(m.doFinal(canonical.getBytes(StandardCharsets.UTF_8))));}catch(Exception e){throw new IllegalStateException(e);}}}
